package br.com.onda;
import org.json.*;
import java.net.URI;
import java.util.*;
import java.util.regex.*;
/** Reads only the requested public item, never recommended posts or executable JavaScript. */
final class TiktokPage {
 static final class Clip {final String title,video;Clip(String title,String video){this.title=title;this.video=video;}}
 static Clip parse(String html,String id)throws Exception{if(html==null||html.length()>8*1024*1024||!id.matches("[0-9]{10,24}"))throw new Exception("Página do vídeo inválida.");for(String name:new String[]{"__UNIVERSAL_DATA_FOR_REHYDRATION__","SIGI_STATE","sigi-persisted-data"}){
  Matcher script=Pattern.compile("<script\\b[^>]*\\bid\\s*=\\s*['\"]"+name+"['\"][^>]*>(.*?)</script\\s*>",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(html);if(!script.find())continue;JSONObject root;try{root=new JSONObject(script.group(1));}catch(JSONException invalid){continue;}JSONObject item=null;if(name.equals("__UNIVERSAL_DATA_FOR_REHYDRATION__")){JSONObject scope=root.optJSONObject("__DEFAULT_SCOPE__"),detail=scope==null?null:scope.optJSONObject("webapp.video-detail");if(detail!=null&&detail.optInt("statusCode",0)!=0)throw new Exception("O TikTok não disponibilizou este vídeo publicamente.");JSONObject info=detail==null?null:detail.optJSONObject("itemInfo");item=info==null?null:info.optJSONObject("itemStruct");}else{JSONObject module=root.optJSONObject("ItemModule");item=module==null?null:module.optJSONObject(id);}if(item==null)continue;if(!id.equals(item.optString("id")))throw new Exception("A página retornou outro vídeo.");if(item.optBoolean("privateItem")||item.optBoolean("isContentClassified")||item.optJSONObject("imagePost")!=null)throw new Exception("Este conteúdo é privado, restrito ou uma publicação de fotos. Use um vídeo público.");JSONObject video=item.optJSONObject("video");if(video==null)continue;
  // Prefer the official download representation; no watermark removal is performed.
  String url=address(video.opt("downloadAddr"));if(url.isEmpty())url=address(video.opt("playAddr"));if(url.isEmpty()){JSONArray rates=video.optJSONArray("bitrateInfo");if(rates!=null)for(int i=0;i<Math.min(20,rates.length());i++){JSONObject rate=rates.optJSONObject(i),play=rate==null?null:rate.optJSONObject("PlayAddr");if(play==null||play.optString("UrlKey").matches(".*(?:bytevc|hvc1|h265).*"))continue;url=address(play);if(!url.isEmpty())break;}}
  if(!url.isEmpty()){String title=item.optString("desc","").trim();if(title.isEmpty())title="TikTok "+id;return new Clip(title.substring(0,Math.min(160,title.length())),url);}
 }
 throw new Exception("O TikTok não expôs um arquivo de vídeo público nesta consulta. Pode exigir verificação, login, estar removido ou ter alterado a página. Tente mais tarde.");}
 static String address(Object value){if(value instanceof String){String text=(String)value;if(text.length()>16384)return "";try{URI uri=new URI(text);if(!MediaLinks.publicShape(uri)||MediaLinks.tiktokHost(uri.getHost()))return "";return uri.toASCIIString();}catch(Exception e){return "";}}if(value instanceof JSONObject){JSONObject object=(JSONObject)value;for(String key:new String[]{"UrlList","urlList","urls"}){Object nested=object.opt(key);String result=address(nested);if(!result.isEmpty())return result;}for(String key:new String[]{"src","url"}){String result=address(object.opt(key));if(!result.isEmpty())return result;}}if(value instanceof JSONArray){JSONArray list=(JSONArray)value;for(int i=0;i<Math.min(10,list.length());i++){String result=address(list.opt(i));if(!result.isEmpty())return result;}}return "";}
}
